          const unsafeZ = Math.abs(predZ) > 0.022 || Math.abs(dz) > 0.023;
          const unsafeY = Math.abs(predY) > 0.100 || Math.abs(dy) > 0.100;
          const gustTransient = distToPlane > 0.05 && gustEdge > 1.15;
          if (distToPlane > 0.02 && (unsafeZ || unsafeY || gustTransient)) {
            phase = 'align';
            centeredCount = 0;
          }
        }

        if (phase === 'align') {
          const ex = alignX - p.x;
          const ey = g.y - p.y;
          const ez = g.z - p.z;
          if (Math.abs(ex) < 0.20) posInt.x = clamp(posInt.x + ex * DT, -0.15, 0.15);
          else posInt.x *= 0.95;

          axDes = clamp(7.5 * ex - 4.8 * v.x + 3.0 * posInt.x, -5.5, 5.5);
          ayDes = clamp(10.5 * ey - 5.4 * v.y + 5.5 * posInt.y, -4.5, 5.5);
          azDes = clamp(14.0 * ez - 6.4 * v.z + 8.0 * posInt.z, -6.5, 6.5);

