            }
          }
        } else {
          // Lunge rapidly through gate while tightly holding y and z
          const targetX = g.x + 0.30;
          const ex = targetX - p.x;
          const ey = g.y - p.y;
          const ez = g.z - p.z;
          axDes = clamp(10.0 * ex - 3.5 * v.x + 2.5, -5.0, 6.5);
          ayDes = clamp(12.0 * ey - 5.6 * v.y + 5.5 * posInt.y, -5.0, 6.0);
          azDes = clamp(15.5 * ez - 7.0 * v.z + 8.5 * posInt.z, -6.8, 6.8);
        }
      } else {
