          const targetY = clamp(0.08 + 0.60 * horizErr, 0.11, 0.85);
          const ey = targetY - p.y;
          axDes = clamp(7.5 * ex - 4.8 * v.x + 4.0 * posInt.x, -5.0, 5.0);
          azDes = clamp(7.5 * ez - 4.8 * v.z + 4.0 * posInt.z, -5.0, 5.0);
          ayDes = clamp(8.0 * ey - 4.8 * v.y, -4.5, 5.0);
          if (horizErr < 0.12 && horizSpeed < 0.35 && p.y < 0.26) {
            phase = 'pad_descend';
          }
        }
        if (phase === 'pad_descend') {
          const targetVy = p.y > 0.13 ? -0.40 : -0.24;
          axDes = clamp(9.0 * ex - 5.2 * v.x + 5.0 * posInt.x, -4.0, 4.0);
          azDes = clamp(9.0 * ez - 5.2 * v.z + 5.0 * posInt.z, -4.0, 4.0);
          ayDes = clamp(9.0 * (targetVy - v.y) + 4.0 * (0.04 - p.y), -3.5, 3.5);
          maxTilt = 0.26;
          if (p.y <= 0.094 && horizErr <= 0.140 && totalSpeed < 0.65) {
