        att.roll + (desAlphaRoll - biasRoll - 22 * simInt.roll + 13 * rates.roll) / 65,
        -0.6,
        0.6
      );
      const pitchCmd = clamp(
        att.pitch + (desAlphaPitch - biasPitch - 22 * simInt.pitch + 13 * rates.pitch) / 65,
        -0.6,
        0.6
      );

