          ayDes = clamp(10.5 * ey - 5.4 * v.y + 5.5 * posInt.y, -4.5, 5.5);
          azDes = clamp(14.5 * ez - 6.6 * v.z + 8.5 * posInt.z, -6.5, 6.5);

