        const pad = obs.pad.centre;
        if (phase !== 'pad_approach' && phase !== 'pad_descend' && phase !== 'pad_pin') {
          phase = 'pad_approach';
          posInt.x = 0;
          posInt.y = 0;
          posInt.z = 0;
        }
        const ex = pad.x - p.x;
        const ez = pad.z - p.z;
        const horizErr = Math.hypot(ex, ez);
        const horizSpeed = Math.hypot(v.x, v.z);
        const totalSpeed = Math.hypot(v.x, v.y, v.z);

