        const canLungeWind = !gustActive || (gustEdge < 0.65 && (gustWaitSteps > 135 || deadlineNear));
        const zTol = deadlineNear ? 0.015 : 0.011;
        const predZTol = deadlineNear ? 0.016 : 0.012;

        const isCentered =
          Math.abs(dz) < zTol &&
          Math.abs(predZ) < predZTol &&
          Math.abs(v.z) < 0.06 &&
          Math.abs(dy) < 0.060 &&
          Math.abs(predY) < 0.070 &&
          Math.abs(v.y) < 0.18 &&
          p.x > g.x - 0.28 &&
          p.x < g.x &&
          canLungeWind;

