          const lungeBoost = obs.gateIndex === 2 ? 1.8 : 2.4;
          const targetX = g.x + lungeOffset;
          const ex = targetX - p.x;
          const ey = g.y - p.y;
          const ez = g.z - p.z;
          axDes = clamp(10.0 * ex - 3.8 * v.x + lungeBoost, -5.0, 6.0);
          ayDes = clamp(12.0 * ey - 5.6 * v.y + 5.5 * posInt.y, -5.0, 6.0);
